create extension if not exists pgcrypto;

do $$ begin create type project_status as enum ('idea','script','production','editing','completed','archived'); exception when duplicate_object then null; end $$;
do $$ begin create type scene_status as enum ('draft','ready','generating','review','approved','completed'); exception when duplicate_object then null; end $$;
do $$ begin create type prompt_type as enum ('image','video','voice','music','negative','style','camera','system'); exception when duplicate_object then null; end $$;
do $$ begin create type prompt_block_type as enum ('character','action','environment','lighting','camera','style','negative'); exception when duplicate_object then null; end $$;
do $$ begin create type asset_type as enum ('image','video','audio','music','reference'); exception when duplicate_object then null; end $$;
do $$ begin create type asset_status as enum ('Draft','Generating','Generated','Approved','Rejected','Archived'); exception when duplicate_object then null; end $$;

create table if not exists users (id uuid primary key default gen_random_uuid(), email text unique not null, name text not null default '', created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists projects (id uuid primary key default gen_random_uuid(), user_id uuid references users(id) on delete cascade, name text not null, description text not null default '', cover_url text not null default '', type text not null default 'film', status project_status not null default 'idea', created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists characters (id uuid primary key default gen_random_uuid(), project_id uuid references projects(id) on delete cascade, name text not null, description text not null default '', appearance text not null default '', role text not null default 'supporting', avatar_url text not null default '', created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists character_references (id uuid primary key default gen_random_uuid(), character_id uuid references characters(id) on delete cascade, asset_id uuid, label text not null default '', created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists locations (id uuid primary key default gen_random_uuid(), project_id uuid references projects(id) on delete cascade, name text not null, description text not null default '', reference_url text not null default '', created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists styles (id uuid primary key default gen_random_uuid(), project_id uuid references projects(id) on delete cascade, name text not null, description text not null default '', prompt text not null default '', preview_url text not null default '', created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists scenes (id uuid primary key default gen_random_uuid(), project_id uuid references projects(id) on delete cascade, number int not null, title text not null, description text not null default '', duration int not null default 30, narration text not null default '', notes text not null default '', status scene_status not null default 'draft', created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(project_id, number));
create table if not exists prompts (id uuid primary key default gen_random_uuid(), project_id uuid references projects(id) on delete cascade, scene_id uuid references scenes(id) on delete set null, type prompt_type not null default 'image', title text not null, content text not null default '', model text not null default '', status text not null default 'draft', created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists prompt_blocks (id uuid primary key default gen_random_uuid(), prompt_id uuid references prompts(id) on delete cascade, type prompt_block_type not null, content text not null default '', sort_order int not null default 0, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists prompt_versions (id uuid primary key default gen_random_uuid(), prompt_id uuid references prompts(id) on delete cascade, version int not null, content text not null default '', created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(prompt_id, version));
create table if not exists assets (id uuid primary key default gen_random_uuid(), project_id uuid references projects(id) on delete cascade, scene_id uuid references scenes(id) on delete set null, type asset_type not null default 'reference', url text not null default '', thumbnail_url text not null default '', version int not null default 1, status asset_status not null default 'Draft', created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists voiceovers (id uuid primary key default gen_random_uuid(), project_id uuid references projects(id) on delete cascade, scene_id uuid references scenes(id) on delete set null, text text not null default '', voice text not null default '', language text not null default 'en', status text not null default 'draft', asset_id uuid references assets(id) on delete set null, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists music (id uuid primary key default gen_random_uuid(), project_id uuid references projects(id) on delete cascade, name text not null, mood text not null default '', genre text not null default '', duration int not null default 60, asset_id uuid references assets(id) on delete set null, status text not null default 'draft', created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists tags (id uuid primary key default gen_random_uuid(), name text unique not null, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists prompt_tags (id uuid primary key default gen_random_uuid(), prompt_id uuid references prompts(id) on delete cascade, tag_id uuid references tags(id) on delete cascade, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(prompt_id, tag_id));

create index if not exists idx_projects_user on projects(user_id);
create index if not exists idx_scenes_project on scenes(project_id, number);
create index if not exists idx_prompts_project_scene on prompts(project_id, scene_id);
create index if not exists idx_assets_project_scene on assets(project_id, scene_id);
